SELECT gen_random_uuid(),CASE WHEN i=1 THEN 'abc-123' ELSE 'tx-'||lpad(i::text,3,'0') END,'usr-'||lpad((((i-1)%50)+1)::text,3,'0'),'rec-'||lpad(i::text,4,'0'),'TR720001002136978165'||lpad((((i-1)%50)+1)::text,6,'0'),(100+i*3.25)::numeric(19,2),'TRY',CASE WHEN i>450 THEN 'REBATE' ELSE 'PAYMENT' END,CASE WHEN i=3 OR (i BETWEEN 451 AND 483 AND i NOT IN (452,453,455)) OR (i<=450 AND i%29=0) THEN 'FAILED' ELSE 'SUCCESS' END,now()-interval '23 hours'+i*interval '2 minutes',now()-interval '23 hours'+i*interval '2 minutes'+interval '5 seconds' FROM generate_series(1,500) i;
UPDATE transactions t SET amount=r.amount,created_at=r.created_at,updated_at=r.created_at+interval '1 second' FROM rebates r WHERE t.transaction_id=r.rebate_transaction_id;
